auto* ctx = this->getContext("2d");
if (ctx == nullptr) {
  return;  // JS 里在 null 上调 clearRect 抛 TypeError，处理函数就此中止
}
ctx->clearRect(0, 0, this->width.get(), this->height.get());

const double amplitude = this->lineWidth.get() * this->amplitudeMultiplier.get();
const double freq = this->frequency.get();  // JS 的局部变量 frequency（改名以免遮蔽成员）
const double phase = js::dateNow() / 400.0;
const double centerY = this->height.get() / 2;

ctx->setStrokeStyle(this->color.get());
// 上下文忽略非正、非有限的 lineWidth（保留上次的值，初始 1），所以下面的循环读回上下文里实际的值
ctx->setLineWidth(this->lineWidth.get());
ctx->setLineCap("round");
ctx->beginPath();
constexpr double kPi = 3.141592653589793;  // Math.PI
for (double px = ctx->lineWidth() / 2; px <= this->width.get() - ctx->lineWidth() / 2; px += 1) {
  const double waveY = centerY + amplitude * std::sin(freq * 2 * kPi * px / this->fullLength.get() + phase);
  // ii: 上下文的 lineWidth 恒为正，px 从 lineWidth / 2 起，px === 0 永不成立，总走 lineTo；
  // 空路径上的 lineTo 按 Canvas 规则先开一条子路径（等同 moveTo）
  if (px == 0) {
    ctx->moveTo(px, waveY);
  } else {
    ctx->lineTo(px, waveY);
  }
}
ctx->stroke();

